diff --git a/tablet/src/api/client.test.ts b/tablet/src/api/client.test.ts
new file mode 100644
index 0000000..c1aa1f6
--- /dev/null
+++ b/tablet/src/api/client.test.ts
@@ -0,0 +1,80 @@
+import { describe, it, expect, vi, beforeEach } from 'vitest'
+
+// preferencesStore's async half (refresh token) goes through the real
+// @capacitor/preferences plugin, which needs a native bridge or a browser
+// `window.localStorage` to back it. Neither exists under vitest's default
+// node environment, so fake the plugin with a plain in-memory map -- this
+// test is exercising apiFetch's retry logic, not Capacitor's storage plugin.
+// Plain functions (not vi.fn) so vi.restoreAllMocks() in beforeEach can't
+// strip their implementation out from under the test.
+const fakePreferences = new Map<string, string>()
+vi.mock('@capacitor/preferences', () => ({
+  Preferences: {
+    get: async ({ key }: { key: string }) => ({ value: fakePreferences.get(key) ?? null }),
+    set: async ({ key, value }: { key: string; value: string }) => {
+      fakePreferences.set(key, value)
+    },
+    remove: async ({ key }: { key: string }) => {
+      fakePreferences.delete(key)
+    },
+  },
+}))
+
+import { setAccessToken, setRefreshToken } from '../auth/preferencesStore'
+
+describe('apiFetch 401 handling', () => {
+  beforeEach(async () => {
+    setAccessToken('old-access-token')
+    await setRefreshToken('a-refresh-token')
+    vi.restoreAllMocks()
+  })
+
+  it('refreshes once and retries once on a 401, then succeeds', async () => {
+    const responses = [
+      new Response(null, { status: 401 }),
+      new Response(JSON.stringify({ access_token: 'new-access-token', refresh_token: 'new-refresh-token' }), { status: 200 }),
+      new Response(JSON.stringify({ ok: true }), { status: 200 }),
+    ]
+    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
+    vi.stubGlobal('fetch', fetchMock)
+
+    const { apiFetch } = await import('./client')
+    const result = await apiFetch<{ ok: boolean }>('/api/v1/zones')
+
+    expect(result).toEqual({ ok: true })
+    expect(fetchMock).toHaveBeenCalledTimes(3)
+    // second call must be the refresh endpoint
+    expect(fetchMock.mock.calls[1][0]).toContain('/api/v1/auth/refresh')
+  })
+
+  it('does not loop -- a second consecutive 401 after refresh throws instead of retrying again', async () => {
+    const responses = [
+      new Response(null, { status: 401 }),
+      new Response(JSON.stringify({ access_token: 'new-access-token', refresh_token: 'new-refresh-token' }), { status: 200 }),
+      new Response(null, { status: 401 }),
+    ]
+    const fetchMock = vi.fn().mockImplementation(() => Promise.resolve(responses.shift()!))
+    vi.stubGlobal('fetch', fetchMock)
+
+    const { apiFetch } = await import('./client')
+
+    await expect(apiFetch('/api/v1/zones')).rejects.toThrow()
+    expect(fetchMock).toHaveBeenCalledTimes(3)
+  })
+
