3	
4	const API_BASE = import.meta.env.VITE_API_BASE_URL as string
5	
6	export interface AuthUser {
7	  id: string
8	  email: string
9	  role: string
10	}
11	
12	interface TokenPair {
13	  access_token: string
14	  refresh_token: string
15	}
16	
17	interface AuthContextValue {
18	  user: AuthUser | null
19	  accessToken: string | null
20	  isLoading: boolean
21	  login: (tenantId: string, email: string, password: string) => Promise<void>
22	  logout: () => Promise<void>
23	}
24	
25	const AuthContext = createContext<AuthContextValue | null>(null)
26	
27	async function fetchMe(accessToken: string): Promise<AuthUser> {
28	  const response = await fetch(`${API_BASE}/api/v1/auth/me`, {
29	    headers: { Authorization: `Bearer ${accessToken}` },
30	  })
31	  if (!response.ok) throw new Error('failed to fetch current user')
32	  return response.json()
33	}
34	
35	async function refreshTokens(refreshToken: string): Promise<TokenPair> {
36	  const response = await fetch(`${API_BASE}/api/v1/auth/refresh`, {
37	    method: 'POST',
38	    headers: { 'Content-Type': 'application/json' },
39	    body: JSON.stringify({ refresh_token: refreshToken }),
40	  })
41	  if (!response.ok) throw new Error('refresh failed')
42	  return response.json()
43	}
44	
45	export function AuthProvider({ children }: { children: ReactNode }) {
46	  const [user, setUser] = useState<AuthUser | null>(null)
47	  const [accessToken, setAccessToken] = useState<string | null>(null)
48	  const [isLoading, setIsLoading] = useState(true)
49	
50	  useEffect(() => {
51	    async function bootstrap() {
52	      try {
53	        const storedRefreshToken = await getRefreshToken()
54	        if (!storedRefreshToken) {
55	          setIsLoading(false)
56	          return
57	        }
58	        const tokens = await refreshTokens(storedRefreshToken)
59	        const me = await fetchMe(tokens.access_token)
60	        if (me.role !== 'rep') {
61	          await setTokens(null, null)
62	          setIsLoading(false)
63	          return
64	        }
65	        await setTokens(tokens.access_token, tokens.refresh_token)
66	        setAccessToken(tokens.access_token)
67	        setUser(me)
68	        setIsLoading(false)
69	      } catch {
70	        setIsLoading(false)
71	        await setTokens(null, null)
72	      }
73	    }
74	    bootstrap()
75	  }, [])
76	
77	  async function login(tenantId: string, email: string, password: string) {
78	    const response = await fetch(`${API_BASE}/api/v1/auth/login`, {
79	      method: 'POST',
80	      headers: { 'Content-Type': 'application/json', 'X-Tenant-Id': tenantId },
81	      body: JSON.stringify({ email, password }),
82	    })
83	    if (!response.ok) throw new Error('invalid credentials')
84	    const tokens: TokenPair = await response.json()
85	    const me = await fetchMe(tokens.access_token)
86	    if (me.role !== 'rep') {
87	      throw new Error('this app is for field reps')
88	    }
89	    await setTokens(tokens.access_token, tokens.refresh_token)
90	    setAccessToken(tokens.access_token)
91	    setUser(me)
92	  }
93	
94	  async function logout() {
95	    await setTokens(null, null)
96	    setAccessToken(null)
97	    setUser(null)
98	  }
99	
100	  return (
101	    <AuthContext.Provider value={{ user, accessToken, isLoading, login, logout }}>
102	      {children}
103	    </AuthContext.Provider>
104	  )
105	}
106	
107	export function useAuth(): AuthContextValue {
